"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["83594"],{8112(e){e.exports=JSON.parse('{"id":"FIN-116","slug":"notes-to-financial-statements","term":"Notes to Financial Statements","also_known_as":[],"difficulty":"Beginner","definition":"Notes to financial statements are the detailed explanations and additional information that accompany the main financial statements and help readers understand the figures.","explanation":["The main statements show totals, but totals alone can hide important details. The notes explain how the figures were calculated and what they include.","Notes typically describe the company\'s accounting policies, such as how it recognises revenue and depreciates assets. They break down large items, such as the types of debt and when they must be repaid, or the main categories of inventory. They also disclose information that does not appear on the statements at all, such as lawsuits, guarantees, commitments to future spending and significant events after the reporting date.","For example, the balance sheet might show total borrowings of 50 million. The notes would explain that this includes a 30 million bond due in three years and a 20 million bank loan due next year, with their interest rates.","Experienced analysts often say the notes are where the real story lies. Changes in accounting policies, large one-off items and risks such as legal claims are usually explained there."],"note":"","total":1500,"prev":{"slug":"normalized-earnings","term":"Normalized Earnings"},"next":{"slug":"off-balance-sheet-financing","term":"Off-Balance-Sheet Financing"}}')}}]);